#!/usr/bin/env python3
"""Summarize real-data outcomes without turning approximate references into truth."""
import hashlib,json,math,pathlib
ROOT=pathlib.Path(__file__).resolve().parents[1]
def distance(lat,lon,ref):
 a,b=map(math.radians,[lat,ref[0]]);dy=b-a;dx=math.radians(ref[1]-lon);h=math.sin(dy/2)**2+math.cos(a)*math.cos(b)*math.sin(dx/2)**2;return 12742000*math.asin(min(1,math.sqrt(h)))
def main():
 primary=[40.876728,-73.526434];secondary=[40.876466,-73.524951]
 methods=[('Ridge default / supplied two aircraft','colsto-assisted-diverse.json'),('High recall ridge / 36 aircraft','colsto-competitive.json'),('Experimental spectral / 36 aircraft','colsto-competitive-spectral-final.json')]
 original=[]
 for name,file in methods:
  path=ROOT/'validation-runs/locations'/file;a=json.loads(path.read_text())['analysis'];entry={'method':name,'result_path':str(path.relative_to(ROOT)),'result_sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'status':a['status'],'events':len(a['events']),'geographic_microphone_error_eligible':False,'search':a['search'],'score_kind':a['score_kind']}
  if a['candidates']:
   c=a['candidates'][0];entry.update(estimate_lat_lon=[c['lat'],c['lon']],estimated_excerpt_start_unix_s=c['start_unix_s'],distance_to_creator_map_reference_m=distance(c['lat'],c['lon'],primary),distance_to_secondary_reconstruction_reference_m=distance(c['lat'],c['lon'],secondary),score=c['score'],matched_ridge_proposals=c['matched_events'],spectral_profiles=c.get('spectral_matches',[]))
  original.append(entry)
 news=[]
 for id in ['fox-thunderbirds','fox-frecce','fox-af1','dvids-yuma']:
  path=ROOT/'validation-runs/locations/news'/(id+'.json');a=json.loads(path.read_text())['analysis'];news.append({'id':id,'status':a['status'],'events':len(a['events']),'flight_segments':len(a['flights']),'estimate_lat_lon':[a['candidates'][0]['lat'],a['candidates'][0]['lon']] if a['candidates'] else None,'accuracy_eligible':False,'reason':'Publisher event-region metadata is not microphone truth; waveform continuity and UTC are unverified.'})
 local=json.loads((ROOT/'docs/local-location-validation.json').read_text());catalog=json.loads((ROOT/'web/data/catalog.json').read_text())
 report={'schema_version':1,'conclusion':'The current locator fails the available real-data validation. Candidate generation and passing software tests must not be represented as validated location accuracy.','original_recording':{'primary_reference_lat_lon':primary,'primary_reference_role':'Map search pin shown by creator at 25:30; not surveyed microphone location','secondary_reference_lat_lon':secondary,'secondary_reference_role':'Previously used reconstruction coordinate; not substituted for creator evidence','date_primary_verified':'2026-09-08','exact_start_utc_primary_verified':False,'methods':original},'news':news,'dlr_local_frame':local,'static_data':{'packages':len(catalog['packages']),'bytes':sum(e['transfer_bytes'] for e in catalog['packages']),'largest_shard_bytes':max(s['bytes'] for e in catalog['packages'] for s in e['shards']),'licenses':sorted({e['license'] for e in catalog['packages']})},'ground_truth_limitations':['DLR has measured source-local receiver coordinates but no geographic origin or UTC; six channels are one correlated jet flyover.','Original creator recording identifies a public site and map reference, not a surveyed microphone coordinate or capture-start UTC.','AeroSonicDB public locations are intentionally shifted, and filename timezone is unstated; not used for coordinate-error claims.','Pathak has original audio/ridges/KML, but no independently verified microphone coordinate or first-sample waveform UTC.'],'reproduce':['python scripts/prepare_dlr_validation.py','python scripts/validate_dlr_locations.py','Original raw inputs and exact configs/results remain under data/location-validation and validation-runs/locations.','python scripts/check_static_data.py dist']}
 (ROOT/'docs/historical-validation.json').write_text(json.dumps(report,indent=2)+'\n')
 lines=['# Historical flight data and actual location validation','',report['conclusion'],'','## Actual estimates on the original recording','','The raw creator-linked 18-minute excerpt is continuous, and only the recording date is supplied as the clock prior. No hand-drawn frequency curves or individual acoustic windows are supplied. The region is a finite Oyster Bay town prior, not a national search. Both high-recall variants are development experiments, not held-out evaluation.','','| Method | Estimated latitude, longitude | Distance to creator map reference | Status |','|---|---|---:|---|']
 for e in original:
  point=', '.join(f'{v:.6f}' for v in e.get('estimate_lat_lon',[])) or 'No estimate';dist=f"{e['distance_to_creator_map_reference_m']/1000:.2f} km" if 'distance_to_creator_map_reference_m' in e else '—';lines.append(f"| {e['method']} | {point} | {dist} | {e['status']} |")
 lines+=['','The creator’s displayed reference is 40.876728, -73.526434. The prior reconstruction coordinate 40.876466, -73.524951 is separately preserved. These distances are to a published reference, not measured microphone errors. The creator’s on-screen date 9/8/26 and visual camera-site identification at 19 Bayview Ave provide stronger evidence than a publication timestamp. Exact waveform UTC remains unverified.','', 'The competitive package contains 36 real aircraft traces selected geographically and without an acoustic score/type filter, including 34 competitors. This is a sample of 133 replay-discovered regional aircraft, so source coverage remains incomplete. The supplied-two-aircraft run is explicitly assisted association.','', '## Measured local receiver positions','']
 for name,g in local['groups'].items():
  med=g['median_error_m_on_answered'];base=g['median_origin_baseline_m_on_answered']
  values=f'median error {med:.1f} m, origin-only baseline {base:.1f} m' if med is not None else 'no coordinate-error statistic because no estimate was returned'
  lines.append(f"- {name}: {g['answers']}/{g['cases']} estimates; {values}; {g['beats_origin_baseline']} estimates beat the origin-only baseline.")
 lines+=['','See [per-channel errors and protocol](LOCAL_LOCATION_VALIDATION.md). The measured-knot protocol uses no extrapolation and returns no usable events. The full 7 s experiment explicitly extends a constant-velocity model from source metadata; it returns inaccurate/ambiguous positions. Both retain the source-clock convention caveat. All six channels share one jet flyover and cannot establish multi-session generalization.','', '## Existing news reports','', '| Recording | Available package segments | Result | Accuracy eligible |','|---|---:|---|---|']
 for n in news:lines.append(f"| {n['id']} | {n['flight_segments']} | {n['status']} | No: microphone/clock metadata absent |")
 lines+=['','AF1 historical positions confirm the reported stadium flyover, but its source trace is MLAT/barometric only. It is retained as historical evidence and excluded from the strict geometric-height package; the available package contains a competitor, not AF1. No barometric height was silently relabeled as geometric. Yuma coverage is sampled, not a complete day. These failures do not prove no aircraft were audible.','', '## What the data changed','', '- Actual readsb archives contain approximately 20 s waypoint spacing. The default interpolation gap limit is now 30 s, while larger gaps remain excluded.','- Duplicate/out-of-order source timestamps and invalid geometric heights were found in real data. Every segment is normalized, and conflicting/invalid points are counted and rejected.','- Event selection now preserves temporal diversity, and every event can propose the common clock. The earliest detected ridge is no longer mandatory.','- Uniform wind is supported and tested against independent propagation geometry.','- Experimental direct-spectrogram scoring tests flight-predicted windows rather than requiring a detected ridge for each flyover. It refuses short clipped evidence, counts distinct spectral frames once, and prevents two aircraft hypotheses from double-counting the same time interval. It still fails this geographic benchmark and is disabled by default.','- Cached automatic events can be searched against competing packages without repeating audio decoding, while recording their original audio fingerprint.','', '## Static hosting deliverables','', f"Seven logical packages contain {report['static_data']['bytes']:,} bytes of flight data; the largest shard is {report['static_data']['largest_shard_bytes']:,} bytes. The complete catalog is lossless after documented source cleaning and includes SHA-256, coverage, coordinate frames and license metadata.",'', 'See [STATIC_DATA.md](STATIC_DATA.md) for GitHub Pages workflow, source attribution, ODbL-derived-database distribution and actual hosting-budget checks. No live repository/site was published.','', '## Next scientific requirement','', 'Do not advertise geographic accuracy yet. The next useful validation set needs several stationary recorders with independently measured geographic position/height, synchronized waveform clocks, continuous propeller-aircraft passes and competing traffic. Algorithm work should focus on faint-pass recall, source-frequency/trajectory model error, null comparisons across the full search and calibrated abstention. The current data exposes those weaknesses rather than concealing them.']
 (ROOT/'docs/HISTORICAL_VALIDATION.md').write_text('\n'.join(lines)+'\n')
 print(report['conclusion']);print(report['static_data'])
if __name__=='__main__':main()
